def _splitWords(s):
	"""'FailToStopT' -> ['Fail', 'To', 'Stop', 'T']; 'IOFault' -> ['IO', 'Fault']."""
	out = []
	for chunk in str(s).replace("_", " ").split():
		word = ""
		for i, ch in enumerate(chunk):
			nxt = chunk[i + 1] if i + 1 < len(chunk) else ""
			if word and ch.isupper() and (word[-1].islower() or word[-1].isdigit() or (nxt and nxt.islower())):
				out.append(word)
				word = ch
			elif word and ch.isdigit() and not word[-1].isdigit():
				out.append(word)
				word = ch
			else:
				word += ch
		if word:
			out.append(word)
	return out


def label(field, deviceType=None):
	"""Plain-English header for a UDT member (default columns first, then LABELS, then a guess)."""
	f = str(field or "")
	if f == "tagPath":
		return DEVICE_LABEL
	for spec in COLUMNS.get(_typeKey(deviceType), []):
		if spec[0] == f:
			return spec[1]
	if f in LABELS:
		return LABELS[f]
	prefix = ""
	rest = f
	for p, word in _PREFIXES:
		if f.startswith(p):
			prefix, rest = word, f[len(p):]
			break
	words = [_WORDS.get(w, w[:1].upper() + w[1:]) for w in _splitWords(rest)]
	return (prefix + " ".join(words)).strip() or f


def _typeKey(typeId):
	return str(typeId or "").split("/")[-1]


def hasFaceplate(typeId):
	return _typeKey(typeId) not in NO_FACEPLATE


def _plain(obj):
	"""Column dicts from Overview/Instances arrive as documents; copy to plain dicts/lists."""
	if hasattr(obj, "keys"):
		return dict((str(k), _plain(obj[k])) for k in obj.keys())
	if isinstance(obj, (list, tuple)) or (hasattr(obj, "__iter__") and not isinstance(obj, basestring)):
		return [_plain(v) for v in obj]
	return obj


def applyColumns(columns, typeId):
	"""Relabel, reorder and hide shared.Overview table columns for one device type."""
	key = _typeKey(typeId)
	specs = COLUMNS.get(key)
	cols = [_plain(c) for c in (columns or [])]
	if specs is None:
		return cols
	byField = dict((str(c.get("field")), c) for c in cols)
	shown = []
	device = byField.pop("tagPath", None)
	if device is not None:
		device["header"]["title"] = DEVICE_LABEL
		device["width"] = DEVICE_WIDTH
		device["strictWidth"] = False
		shown.append(device)
	for field, title, fmt, width in specs:
		col = byField.pop(field, None)
		if col is None:
			continue
		col["header"]["title"] = title
		col["visible"] = True
		col["width"] = width
		col["strictWidth"] = False
		if fmt is not None:
			col["viewPath"] = "03_Elements/03_Table/StateText"
			if isinstance(fmt, dict):
				col["viewParams"] = {"value": "", "states": dict(fmt), "format": "",
									 "commLoss": field in STATE_WORD.get(key, ())}
			else:
				col["viewParams"] = {"value": "", "states": {}, "format": fmt}
		shown.append(col)
	hidden = []
	for col in cols:
		field = str(col.get("field"))
		if field not in byField:
			continue
		col["header"]["title"] = label(field, key)
		col["visible"] = False
		hidden.append(col)
	return shown + hidden
